WITH reference AS (SELECT * FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,b.highPrice AS high_current,CASE WHEN COUNT(b.highPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW)=250 THEN MIN(b.highPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW) ELSE NULL END AS high_min250,CASE WHEN COUNT(b.highPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW)=250 THEN MAX(b.highPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW) ELSE NULL END AS high_max250 FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate<='2026-04-13') w WHERE bizdate='2026-04-13'), feature AS(SELECT f.* FROM dsl_rolling_diag_9ea343e784da.rolling_averages_v1 f WHERE f.bizdate='2026-04-13' AND f.snapshot_id='stock-20060104-20260414-v1' AND f.manifest_sha256='306f333e28c82c9f2c634d8a1eb64eb49d3092937d8ca7d2742d96ecdcf21a95' AND f.registry_fingerprint='a460a741b13b2cea6066c7a973c246463d68c6eb083c07a50650ed8403f3ab17') SELECT COUNT(*) FROM reference w FULL OUTER JOIN feature f ON w.mktcode=f.mktcode AND w.tgtcode=f.tgtcode WHERE w.mktcode IS NULL OR f.mktcode IS NULL OR NOT(f.high_current <=> w.high_current) OR NOT(f.high_min250 <=> w.high_min250) OR NOT(f.high_max250 <=> w.high_max250);
